int dp[101][101];
int n;

int find(int x, int y, vector<vector<int>>& g)
{
    if(x == n)
        return 0;

    if(dp[x][y] != -100000)
        return dp[x][y];

    int ans = g[x][y] + find(x+1, y, g);

    if(y-1>=0)
        ans = min(ans, g[x][y] + find(x+1, y-1, g) );

    if(y+1!=n)
        ans = min(ans, g[x][y] + find(x+1, y+1, g) );

    return dp[x][y] = ans;
}

