class Solution(object):
    def minFallingPathSum(self, A):
        """
        :type A: List[List[int]]
        :rtype: int
        """
        n = len(A)
        dp = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[0][i] = A[0][i]
        for i in range(1, n):
            for j in range(n):
                prev_min = dp[i - 1][j]
                if j - 1 >= 0:
                    prev_min = min(prev_min, dp[i - 1][j - 1])
                if j + 1 < n:
                    prev_min = min(prev_min, dp[i - 1][j + 1])
                dp[i][j] = prev_min + A[i][j]
        return min(dp[-1])
